def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if os.path.basename(root) == "documentation" or not os.path.exists(
            os.path.join(root, "LEDGER_CONSOLIDATED.md")):
        print("ERROR: run this from the orrery repository ROOT. NOTHING was "
              "written.")
        return 1
    planned, problems = [], []
    for name, base_fp, want_fp, hunks in EDITS:
        raw = open(os.path.join(root, name), "rb").read()
        crlf = b"\r\n" in raw
        text = raw.replace(b"\r\n", b"\n")
        actual = hashlib.md5(text).hexdigest()
        if actual == want_fp:
            problems.append("%s: already carries this patch -- a second run" % name)
            continue
        if actual != base_fp:
            problems.append("%s: BASE MOVED (expected %s, found %s)"
                            % (name, base_fp[:12], actual[:12]))
            continue
        text = text.decode("utf-8")
        for index, (old, new) in enumerate(hunks, 1):
            if text.count(old) != 1:
                problems.append("%s: ANCHOR FAIL on edit %d of %d"
                                % (name, index, len(hunks)))
                break
            text = text.replace(old, new)
        else:
            out = text.encode("ascii")
            if hashlib.md5(out).hexdigest() != want_fp:
                problems.append("%s: the result is not the file this patch "
                                "was built to produce" % name)
                continue
            planned.append((name, out, crlf, len(hunks)))
    if problems:
        print("FAILURE -- NOTHING was written:")
        for line in problems:
            print("  " + line)
        return 1
    for name, out, crlf, n in planned:
        if crlf:
            out = out.replace(b"\n", b"\r\n")
        open(os.path.join(root, name), "wb").write(out)
        print("ok  %-48s %d edit(s)" % (name, n))
    print("")
    print("DO THESE, IN THIS ORDER:")
    print("  1. Run the orrery maintenance run. Its 'Ledger index' generator "
          "rewrites the index tables for the twenty new rows.")
    print("  2. Move this script into documentation/.")
    print("  3. Commit and push.")
    print("Undo before committing is Discard Changes in GitHub Desktop.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
